{noformat}public static void mergeAccount(Account main, Account secondary) {
        try{
            merge main secondary;
        } catch (DmlException e) {
            if (String.valueOf(e).contains('UNABLE_TO_LOCK_ROW')) {
                CaseTriggerHandler.QueueableWrapper q = new CaseTriggerHandler.QueueableWrapper();
                q.actionType = 'mergeAccounts';
                q.mapOfData = new Map<String,Object>();
                q.mapOfData.put('main', main);
                q.mapOfData.put('secondary', secondary);
                if(!Test.isRunningTest() && !System.isQueueable() && !System.isBatch()) {
                    System.enqueueJob(new Queueable_Generic(new List<CaseTriggerHandler.QueueableWrapper>{q}));
                }
                return;
            }
            throw e;
        }
    }{noformat}

