{noformat}view: bb_growth_campaigns_info {
    # owner:@farhad.tahmazov
    derived_table: {
      sql:
with en as (
    select
            a.test_id,
            a.treatment_id,
            a.target_id as business_company_id,
            a.domain,
            a.created_date as enrollment_date,
            b.treatment_type,
            tt.country,
            cast(tt.start as date) as test_start_date,
            cast(tt.end as date) as test_end_date,
            get_json_object(b.data,'$.ids[0]') as campaign_id,
            get_json_object(b.data,'$.type') as campaign_type
            --MIN(CAST(a.created_date AS DATE)) AS enrollment_date
            from ng_public_spark.campaign_targeting_enrollment a
            left join ng_public_spark.campaign_tests_treatment b on b.id=a.treatment_id
            left join ng_public_spark.campaign_tests_test tt on tt.id=a.test_id
            where a.created_date > date'2024-01-01'
            and b.created_date >  date'2024-01-01'
            and tt.created_date > date'2024-01-01'
            and a.domain = 'business'
            ),
        campaign_data as (
        select
            id,
            country,
            created_date,
            target_group,
            metadata,
            get_json_object(metadata,'$.lcm_trips') as max_usages_by_same_user,
            get_json_object(metadata,'$.lcm_segment') as cohort_segment,
            get_json_object(metadata,'$.lcm_percentage') as bonus_percentage,
            get_json_object(metadata,'$.lcm_max_discount') as bonus_max_value
            from ng_public_spark.comms_only_campaigns_comms_only_campaign
            where target_group='business'
        )
select
  en.campaign_id,
  en.domain,
  en.campaign_type,
  en.test_start_date AS start_date,
  en.enrollment_date,
  en.test_end_date   AS end_date,
  en.business_company_id,
  en.test_id,
  en.treatment_id,
  en.country,
  cmp.bonus_percentage,
  cmp.bonus_max_value,
  cmp.max_usages_by_same_user,
  cmp.cohort_segment
FROM en
LEFT JOIN campaign_data cmp ON cmp.id = en.campaign_id
ORDER BY en.test_start_date DESC, en.enrollment_date DESC
      ;;
    sql_trigger_value: SELECT FLOOR((UNIX_TIMESTAMP(CURRENT_TIMESTAMP()) - 60*60*5) / (60*60*24)) ;;
  }

  dimension_group: date {
    type: time
    timeframes: [
      date,
      week,
      month,
      quarter,
      year,
    ]
    sql: ${TABLE}.start_date ;;
    label: "Date"
    description: "Group of different time periods to group by or filter the information"
    convert_tz: no
  }

  dimension: dynamic_timeframe {
    type: string
    label_from_parameter: timeframe_picker
    sql: {% case timeframe_picker._parameter_value %}
          {% when "'Date'" %} ${date_date}
          {% when "'Week'" %}  ${date_week}
          {% when "'Month'" %}  ${date_month}
          {% when "'Quarter'" %} ${date_quarter}
          {% when "'Year'" %} ${date_year}
          {% endcase %} ;;
    tags: ["spectacles: ignore"]
  }

  dimension_group: enrollment_date {
    type: time
    timeframes: [
      date,
      week,
      month,
      quarter,
      year,
    ]
    sql: ${TABLE}.enrollment_date ;;
    label: "Enrollment Date"
    convert_tz: no
  }

  dimension_group: end_date {
    type: time
    timeframes: [
      date,
      week,
      month,
      quarter,
      year,
    ]
    sql: ${TABLE}.end_date ;;
    label: "End Date"
    convert_tz: no
  }

  dimension: campaign_id { type: string sql: ${TABLE}.campaign_id ;; }
  dimension: domain { type: string sql: ${TABLE}.domain ;; }
  dimension: campaign_type { type: string sql: ${TABLE}.campaign_type ;; }
  dimension: business_company_id { type: number sql: ${TABLE}.business_company_id ;; }
  dimension: test_id { type: string sql: ${TABLE}.test_id ;; }
  dimension: treatment_id { type: string sql: ${TABLE}.treatment_id ;; }
  dimension: country { type: string sql: ${TABLE}.country ;; }
  dimension: cohort_segment { type: string sql: ${TABLE}.cohort_segment ;; }
  dimension: max_usages_by_same_user { type: string sql: ${TABLE}.max_usages_by_same_user ;; }
  dimension: bonus_percentage { type: string sql: ${TABLE}.bonus_percentage ;; }
  dimension: bonus_max_value { type: string sql: ${TABLE}.bonus_max_value ;; }

  parameter: timeframe_picker {
    default_value: "Month"
    allowed_value: { label: "Date" value: "Date" }
    allowed_value: { label: "Week" value: "Week" }
    allowed_value: { label: "Month" value: "Month" }
    allowed_value: { label: "Quarter" value: "Quarter" }
    allowed_value: { label: "Year" value: "Year" }
    description: "Filter to select for which period you want data to be aggregated. (Date,Week,Month,Quarter,Year)"
  }
}
