{color:red}*Joel Palgi [wrote|https://taxify.slack.com/archives/C02FP2YL06L/p1763711299387299]*{color}:
Data now exists in databricks  and <@U08RKV2V0JJ>
How we fetch sessions for the portal (full code for the process [here|https://github.com/bolteu/bolt-server/blob/00021d98a00ec763c4f90385fd15183ebc4251c5/src/rides/driver/driver_session_history/main/service/SessionService.ts#L58])
{code}SELECT s.id, s.company_id, s.driver_id, s.vehicle_id, s.session_key, UNIX_TIMESTAMP(s.start) start, UNIX_TIMESTAMP(s.end) end
FROM ${TableIds.session} s
WHERE s.company_id = ${data.company_id}
  AND s.start &gt;= FROM_UNIXTIME(${data.start})
  AND s.start &lt;= FROM_UNIXTIME(${data.end})
ORDER BY s.start DESC, s.end DESC{code}
Then we fetch session segments
{code}SELECT segment_key,
       session_id,
       UNIX_TIMESTAMP(start) start,
       UNIX_TIMESTAMP(end)   end,
       waiting_orders_seconds,
       has_order_seconds,
       order_count_finished,
       order_count_cancelled,
       order_count_rejected,
       order_earnings_cash,
       order_earnings_terminal,
       order_earnings_app,
       order_earnings_business
FROM ${TableIds.sessionSegment}
WHERE session_id IN (${sessionIds})
ORDER BY segment_key{code}
Then we create sessions for each session we fetched
{code}const startMoment = moment.unix(session.start).tz(timezone);
const endMoment = session.end ? moment.unix(session.end).tz(timezone) : [moment.tz|http://moment.tz](timezone);
const sessionTotalSeconds = endMoment.diff(startMoment, "seconds");
const driver = driversMap.get(session.driver_id);
const vehicle = vehiclesMap.get(session.vehicle_id);
return {
  id: session.id,
  driver_id: session.driver_id,
  driver_name: driver?.driver_name ?? "",
  vehicle_id: session.vehicle_id,
  vehicle_model: vehicle?.model ?? "",
  vehicle_year: String(vehicle?.year ?? ""),
  vehicle_color: vehicle?.color ?? null,
  vehicle_reg_number: vehicle?.reg_number ?? "",
  start: session.start,
  end: session.end,
  session_key: session.session_key,
  session_total_seconds: sessionTotalSeconds,
  break_total_seconds: 0,
  online_hours_in_seconds: 0,
  has_order_seconds: 0,
  waiting_orders_seconds: 0,
  orders: {
    total: 0,
    orders_finished: 0,
    orders_cancelled: 0,
    orders_rejected: 0
  },
  earnings: {
    total: 0,
    earnings_cash: 0,
    earnings_terminal: 0,
    earnings_app: 0,
    earnings_business: 0
  },
  segments_dates: []
};{code}
And add each segments data to the session (mapping segments to sessions by session_id)
{code}// Segments are sorted already in db query
sessionData.segments_dates.push({
  start: segment.start,
  end: segment.end
});
if (sessionData.segments_dates.length &gt; 1) {
  const beforeTheLastSegment = sessionData.segments_dates[sessionData.segments_dates.length - 2];
  const lastSegment = sessionData.segments_dates[sessionData.segments_dates.length - 1];
  const breakSeconds = lastSegment.start - beforeTheLastSegment.end!;
  sessionData.break_total_seconds += breakSeconds;
}
sessionData.online_hours_in_seconds += segment.has_order_seconds + segment.waiting_orders_seconds;
sessionData.has_order_seconds += segment.has_order_seconds;
sessionData.waiting_orders_seconds += segment.waiting_orders_seconds;
sessionData.orders.total +=
segment.order_count_finished + segment.order_count_cancelled + segment.order_count_rejected;
sessionData.orders.orders_finished += segment.order_count_finished;
sessionData.orders.orders_rejected += segment.order_count_rejected;
sessionData.orders.orders_cancelled += segment.order_count_cancelled;
sessionData.earnings.total +=
  segment.order_earnings_app +
  segment.order_earnings_cash +
  segment.order_earnings_terminal +
  segment.order_earnings_business;
sessionData.earnings.earnings_app += segment.order_earnings_app;
sessionData.earnings.earnings_cash += segment.order_earnings_cash;
sessionData.earnings.earnings_terminal += segment.order_earnings_terminal;
sessionData.earnings.earnings_business += segment.order_earnings_business;{code}
Basically sessions can consist of multiple segments (as driver can be online and on break)

