The steps were:

# Add a volume
# {{mkfs.xfs -f /dev/nvme1n1}}
# {{mkdir -p /mnt/coredump}}
# {{vim /etc/fstab}} and add there {{/dev/nvme1n1  /mnt/coredump   xfs   noatime,nodiratime   0 0}}
# {{mount -a}}
# {{chown tidb:tidb /mnt/coredump}}
# {{chmod 755 /mnt/coredump}}
# Go to {{/tidb-deploy/tikv-20160/conf/tikv.toml}} and add {{abort-on-panic = true}} in the beginning of the file
# Add the following with  {{systemctl edit tikv-20160}}
{noformat}[Service]
LimitCORE=infinity
Environment="COREDUMP_PROGRAM=kernel"
Environment="RUST_BACKTRACE=1"{noformat}
# {{systemctl daemon-reload}}
# {{systemctl restart tikv-20160}}
# 
{noformat}sudo tee /etc/sysctl.d/99-tikv-coredump.conf <<EOF
kernel.core_pattern=/mnt/coredump/core.%e.%p.%h.%t
EOF{noformat}

# {{sudo sysctl --system}}
# {{kill -SIGABRT $(pidof tikv-server)}}

